#nullable enable // autogenerated

using System;
using System.Xml;
using MVZ2.IO;
using MVZ2Logic.Resources;
using PVZEngine;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.Metas
{
    public class CurseMeta
    {

        public string ID { get; private set; }
        public string Name { get; private set; } = string.Empty;
        public string Tooltip { get; private set; } = string.Empty;
        public XMLConditionList? UnlockConditions { get; private set; }
        public SpriteReference? Sprite { get; private set; }
        public NamespaceID? BuffID { get; private set; }
        public CurseMeta(string id)
        {
            ID = id;
        }
        public static CurseMeta? FromXmlNode(XmlNode node, string defaultNsp, int order)
        {
            var id = node.GetAttribute("id");
            if (string.IsNullOrEmpty(id))
            {
                Log.LogError("The ID of an ArtifactMeta is invalid.");
                return null;
            }
            string name = string.Empty;
            string tooltip = string.Empty;
            var textsNode = node["texts"];
            if (textsNode != null)
            {
                name = textsNode.GetAttribute("name") ?? name;
                tooltip = textsNode.GetAttribute("tooltip") ?? tooltip;
            }
            XMLConditionList? conditions = null;
            var unlockNode = node["unlock"];
            if (unlockNode != null)
            {
                conditions = XMLConditionList.FromXmlNode(unlockNode, defaultNsp);
            }
            SpriteReference? sprite = null;
            var spriteNode = node["sprite"];
            if (spriteNode != null)
            {
                sprite = spriteNode.GetAttributeSpriteReference("id", defaultNsp) ?? sprite;
            }
            NamespaceID? buffID = null;
            var buffNode = node["buff"];
            if (buffNode != null)
            {
                buffID = buffNode.GetAttributeNamespaceID("id", defaultNsp) ?? buffID;
            }
            return new CurseMeta(id)
            {
                Name = name,
                Tooltip = tooltip,
                UnlockConditions = conditions,
                Sprite = sprite,
                BuffID = buffID,
            };
        }
    }
}
